 const today=new Date().toISOString().slice(0,10);const soon=new Date(Date.now()+30*86400000).toISOString().slice(0,10);
 async function reload(){
  if(!supabase){setRoleLoading(false);setMsg('Supabase client is not configured. Check NEXT_PUBLIC_SUPABASE_URL and NEXT_PUBLIC_SUPABASE_ANON_KEY in .env.local, then restart npm run dev.');return}
  setMsg('Loading pharmacy catalogue and stock…');
  const {data:{user},error:userError}=await supabase.auth.getUser();
  if(userError||!user){setRoleLoading(false);setMsg(userError?.message||'No active Supabase session. Sign in again, then reopen Pharmacy.');return}
  const storedClinicId=getActiveClinicId();
  const {data:members,error:memberError}=await supabase.from('clinic_members').select('clinic_id,role').eq('user_id',user.id).eq('active',true);
  if(memberError){setRoleLoading(false);setMsg(`Could not resolve your clinic membership: ${memberError.message}`);return}
  const allowed=(members||[]) as Array<{clinic_id:string;role:string}>;
  let membership=allowed.find(x=>x.clinic_id===storedClinicId);
  if(!membership&&allowed.length===1){membership=allowed[0];setActiveClinicId(membership.clinic_id)}
  if(!membership){setRoleLoading(false);setMsg(`Selected clinic does not match an active clinic membership. Selected clinic: ${storedClinicId||'none'}. Active clinic memberships found: ${allowed.length}. Select NH3 Clinic again from the clinic switcher.`);return}
  const clinicId=membership.clinic_id;setRole(membership.role);setRoleLoading(false);
  const [{data:m,error:me},{data:b,error:be},{data:p,error:pe},{data:r,error:re},{data:cs,error:cse},{data:sup,error:supError},{data:adms,error:admsError},{data:parchiRows,error:parchiError}]=await Promise.all([
   supabase.from('medications').select('id,name,generic_name,strength,dosage_form,reorder_level,tax_percent,active,product_category,sku,hsn_code,unit_name,manufacturer').eq('clinic_id',clinicId).eq('active',true).order('name').limit(1000),
   supabase.from('inventory_batches').select('id,medication_id,batch_number,expiry_date,quantity_on_hand,purchase_rate,sale_rate,supplier_name').eq('clinic_id',clinicId).order('expiry_date').limit(2000),
   supabase.rpc('clinic_patient_directory',{p_clinic_id:clinicId}),
   supabase.from('prescriptions').select('id,prescription_no,patient_id,valid_until,status,prescription_items(medication_id,medicine_name,quantity,dose,frequency)').eq('clinic_id',clinicId).in('status',['signed']).gte('valid_until',today).order('prescribed_at',{ascending:false}).limit(300),
   supabase.from('clinic_settings').select('settings').eq('clinic_id',clinicId).maybeSingle(),
   supabase.from('pharmacy_suppliers').select('id,supplier_name,phone,email,gstin,address,notes,active').eq('clinic_id',clinicId).eq('active',true).order('supplier_name').limit(1000),
   supabase.from('admissions').select('id,admission_no,patient_id,status').eq('clinic_id',clinicId).in('status',['admitted','transferred']).order('admitted_at',{ascending:false}).limit(300),
   supabase.from('opd_visits').select('id,visit_no,patient_id,complaint,department,doctor_name,issued_at,handwritten_parchi_image_url,diagnosis,doctor_notes,prescribed_medicines,status').eq('clinic_id',clinicId).not('handwritten_parchi_image_url','is',null).order('updated_at',{ascending:false}).limit(200)
  ]);
  if(me||be||pe||re||cse){setMsg(`Pharmacy data load issue for clinic ${clinicId}: ${[me&&`products: ${me.message}`,be&&`stock: ${be.message}`,pe&&`patients: ${pe.message}`,re&&`prescriptions: ${re.message}`,cse&&`settings: ${cse.message}`].filter(Boolean).join(' | ')}`)}
  else if(!m?.length&&!b?.length){setMsg('No medicines or stock batches were found for this clinic. Check the selected clinic and add medicines or receive stock to begin pharmacy operations.')}
  else if(!m?.length||!b?.length){setMsg(`Partial pharmacy data for clinic ${clinicId}: ${m?.length||0} active products, ${b?.length||0} stock batches. Check RLS policies or clinic_id consistency.`)}
  else setMsg(`Pharmacy data loaded: ${m.length} active products and ${b.length} stock batches for clinic ${clinicId}.`);
  if(m)setItems(m as Medicine[]);if(b)setBatches(b as Batch[]);if(p)setPatients(p.map(patientFromRow));if(r)setRxs(r as Rx[]);if(parchiRows)setHandwrittenParchis(parchiRows as HandwrittenParchi[]);if(parchiError)setMsg(prev=>[prev,`Doctor parchi inbox: ${parchiError.message}`].filter(Boolean).join(' | '));if(sup)setSuppliers(sup as Supplier[]);if(adms)setActiveAdmissions(adms as typeof activeAdmissions);if(admsError)setMsg(prev=>[prev,'IPD admissions: '+admsError.message].filter(Boolean).join(' | '));if(supError)setMsg((prev)=>[prev,`Suppliers: ${supError.message}`].filter(Boolean).join(' | '));
  if(cs?.settings?.pharmacy){const x=cs.settings.pharmacy;setStoreName(x.storeName||'Pharmacy Store');setGstin(x.gstin||'');setInvoicePrefix(x.invoicePrefix||'PH');setDefaultGst(x.defaultGst||'5');setStoreAddress(x.storeAddress||'');setStorePhone(x.storePhone||'');setStoreEmail(x.storeEmail||'');setDrugLicense(x.drugLicense||'');setLogoUrl(x.logoUrl||'')}
 }
 async function loadReports(){const clinicId=getActiveClinicId();if(!supabase||!clinicId){setMsg('Select a clinic first.');return}setReportLoading(true);const {data:lineRows,error:lineError}=await supabase.from('invoice_items').select('invoice_id').eq('clinic_id',clinicId).eq('item_type','pharmacy').limit(5000);if(lineError){setMsg(lineError.message);setReportLoading(false);return}const ids=[...new Set((lineRows||[]).map((x:{invoice_id:string})=>x.invoice_id))];if(!ids.length){setReportInvoices([]);setReportLoading(false);return}const {data,error}=await supabase.from('invoices').select('id,invoice_no,patient_id,subtotal,tax_amount,total_amount,paid_amount,status,created_at').eq('clinic_id',clinicId).in('id',ids).gte('created_at',reportFrom+'T00:00:00').lte('created_at',reportTo+'T23:59:59').order('created_at',{ascending:false}).limit(2000);if(error)setMsg(error.message);else setReportInvoices((data||[]) as typeof reportInvoices);setReportLoading(false)}
 function exportCsv(filename:string,rows:(string|number)[][]){const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();URL.revokeObjectURL(url)}
 async function loadPurchaseHistory(){const clinicId=getActiveClinicId();if(!supabase||!clinicId)return;const {data,error}=await supabase.from('pharmacy_goods_receipts').select('id,grn_no,supplier_id,supplier_invoice_no,supplier_invoice_date,invoice_total,notes,received_at,items:pharmacy_goods_receipt_items(id,medication_id,batch_number,expiry_date,quantity,free_quantity,purchase_rate,sale_rate,tax_percent)').eq('clinic_id',clinicId).order('received_at',{ascending:false}).limit(100);if(error){setMsg('Purchase history: '+error.message);return}setPurchaseHistory((data||[]) as typeof purchaseHistory)}
 function printPurchaseReceipt(receipt:typeof purchaseHistory[number]){const w=window.open('','_blank','width=900,height=700');if(!w){setMsg('Allow pop-ups to print the purchase invoice.');return}const esc=(v:unknown)=>String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');const rows=(receipt.items||[]).map((x,i)=>`<tr><td>${i+1}</td><td>${esc(items.find(m=>m.id===x.medication_id)?.name||'Medicine')}</td><td>${esc(x.batch_number)}</td><td>${esc(x.expiry_date||'—')}</td><td>${Number(x.quantity)+Number(x.free_quantity||0)}</td><td>${Number(x.purchase_rate).toFixed(2)}</td><td>${(Number(x.quantity)*Number(x.purchase_rate)).toFixed(2)}</td></tr>`).join('');const supplier=suppliers.find(x=>x.id===receipt.supplier_id)?.supplier_name||'Supplier';w.document.write(`<!doctype html><html><head><title>${esc(receipt.supplier_invoice_no||receipt.grn_no)}</title><style>body{font:14px Arial;padding:28px;color:#183653}h1{color:#12528a;margin:0 0 6px}header{display:flex;justify-content:space-between;border-bottom:2px solid #176ec2;padding-bottom:16px;margin-bottom:20px}table{width:100%;border-collapse:collapse;margin-top:24px}th,td{border:1px solid #ccd9e6;padding:9px;text-align:left}th{background:#e8f2fc}.total{text-align:right;font-size:18px;font-weight:bold;margin-top:20px}</style></head><body><header><div><h1>${esc(storeName||'Pharmacy')}</h1><b>Goods Receipt / Purchase Invoice</b><p>${esc(storeAddress)}</p></div><div><b>GRN:</b> ${esc(receipt.grn_no)}<br><b>Supplier Invoice:</b> ${esc(receipt.supplier_invoice_no||'—')}<br><b>Date:</b> ${esc(receipt.supplier_invoice_date||receipt.received_at)}<br><b>Supplier:</b> ${esc(supplier)}</div></header><p><b>Remarks:</b> ${esc(receipt.notes||'—')}</p><table><thead><tr><th>#</th><th>Medicine</th><th>Batch</th><th>Expiry</th><th>Qty incl. free</th><th>Rate</th><th>Amount</th></tr></thead><tbody>${rows}</tbody></table><div class="total">Invoice Total: ₹${Number(receipt.invoice_total).toFixed(2)}</div><p style="margin-top:50px">Received by: ____________________ &nbsp;&nbsp;&nbsp; Authorized signature: ____________________</p></body></html>`);w.document.close();w.focus();w.print()}

 function normalizeOcrText(value:string){return value.toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
 function applyPurchaseOcrText(text:string){
   const lines=text.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
   const normalized=normalizeOcrText(text);
   const supplier=suppliers.find(x=>normalizeOcrText(x.supplier_name).length>2 && normalized.includes(normalizeOcrText(x.supplier_name)));
   if(supplier)setPurchaseForm(old=>({...old,supplier_id:supplier.id}));
   const invoiceMatch=text.match(/(?:invoice|bill|inv)\s*(?:no\.?|number|#)?\s*[:\-]?\s*([A-Z0-9\/\-]{3,})/i);
   if(invoiceMatch)setPurchaseForm(old=>({...old,invoice_no:invoiceMatch[1].replace(/[.,]$/,'')}));
   const dateMatch=text.match(/(?:invoice\s*date|bill\s*date|date)\s*[:\-]?\s*(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/i);
   if(dateMatch){const parts=dateMatch[1].split(/[\/\-]/);let d=Number(parts[0]),m=Number(parts[1]),y=Number(parts[2]);if(y<100)y+=2000;if(d>0&&d<=31&&m>0&&m<=12)setPurchaseForm(old=>({...old,purchase_date:`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`}))}
   const parsed:Array<{medication_id:string;batch_number:string;expiry_date:string;quantity:string;free_quantity:string;purchase_rate:string;sale_rate:string;salt_composition:string}> = [];
   for(const line of lines){
     const n=normalizeOcrText(line); if(n.length<8)continue;
     const medicine=items.map(m=>({m,score:normalizeOcrText(m.name+' '+(m.generic_name||'')+' '+(m.strength||'')).split(' ').filter(w=>w.length>3&&n.includes(w)).length})).sort((a,b)=>b.score-a.score)[0];
     const saltMatch=line.match(/(?:salt|composition|generic)\s*[:\-]\s*([^|;]+)/i);if(!medicine||medicine.score===0){if(saltMatch||/(?:batch|b\.?no\.?|qty|quantity)\s*[:#\-]/i.test(line)){const batch=line.match(/(?:batch|b\.?no\.?)\s*[:#\-]?\s*([A-Z0-9\-\/]+)/i);const expiry=line.match(/(?:exp|expiry)\s*[:\-]?\s*(\d{1,2}[\/\-]\d{2,4}|\d{4}-\d{2}-\d{2})/i);const qty=line.match(/(?:qty|quantity)\s*[:\-]?\s*(\d+(?:\.\d+)?)/i);const rate=line.match(/(?:rate|ptr|purchase)\s*[:\-]?\s*(\d+(?:\.\d+)?)/i);parsed.push({medication_id:'',batch_number:batch?.[1]||'',expiry_date:expiry?.[1]||'',quantity:qty?.[1]||'1',free_quantity:'0',purchase_rate:rate?.[1]||'0',sale_rate:'0',salt_composition:saltMatch?.[1]?.trim()||''})}continue;}
     const batchMatch=line.match(/(?:batch|b\.?no\.?)\s*[:#\-]?\s*([A-Z0-9\-\/]+)/i);
     const expiryMatch=line.match(/(?:exp|expiry)\s*[:\-]?\s*(\d{1,2}[\/\-]\d{2,4}|\d{4}-\d{2}-\d{2})/i);
     const nums=(line.match(/\d+(?:\.\d{1,2})?/g)||[]).map(Number);
     const qtyMatch=line.match(/(?:qty|quantity)\s*[:\-]?\s*(\d+(?:\.\d+)?)/i);
     const rateMatch=line.match(/(?:rate|ptr|purchase)\s*[:\-]?\s*(\d+(?:\.\d+)?)/i);
     const expiry=expiryMatch?.[1]||'';
     let expiryDate='';
     if(expiry){if(/^\d{4}-/.test(expiry))expiryDate=expiry;else{const [mm,yy]=expiry.split(/[\/\-]/);const year=Number(yy)<100?2000+Number(yy):Number(yy);if(Number(mm)>=1&&Number(mm)<=12)expiryDate=`${year}-${String(mm).padStart(2,'0')}-01`}}
     parsed.push({medication_id:medicine.m.id,batch_number:batchMatch?.[1]||'',expiry_date:expiryDate,quantity:qtyMatch?.[1]||String(nums.length>0?nums[nums.length-2]||1:1),free_quantity:'0',purchase_rate:rateMatch?.[1]||'0',sale_rate:'0',salt_composition:saltMatch?.[1]?.trim()||medicine.m.generic_name||''});
   }
   if(parsed.length)setPurchaseLines(parsed);
   setPurchaseOcrText(text);
   setPurchaseOcrNotice(`AI extracted ${parsed.length} purchase line(s), including salt / composition where printed. Match any unlinked medicine to your catalogue, verify the salt, batch, expiry, quantity and rates, then save purchase.`);
 }
 async function scanPurchaseBill(file?:File){
   if(!file)return;
   if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type)){setPurchaseOcrNotice('Please upload a JPG, PNG, WEBP or PDF bill.');return}
   if(file.size>15*1024*1024){setPurchaseOcrNotice('Bill must be 15 MB or smaller.');return}
   setPurchaseBillName(file.name);setPurchaseOcrBusy(true);setPurchaseOcrNotice('AI Engine: trying Gemini Primary, then Groq + OCR backup…');
   try{
     const body=new FormData();body.append('file',file);
     const {data:sessionData}=await supabase!.auth.getSession();
     const response=await fetch('/api/pharmacy/purchase-ocr',{method:'POST',headers:sessionData.session?.access_token?{Authorization:`Bearer ${sessionData.session.access_token}`}:{},body});
     const result=await response.json();
     if(!response.ok)throw new Error(result.error||'AI Engine could not read this bill.');
     applyPurchaseOcrText(String(result.text||''));
     setPurchaseOcrNotice(`${result.provider==='gemini'?'Gemini Primary':`Groq Backup (${result.ocrProvider||'OCR'})`} extraction complete. Review supplier, invoice, every medicine, batch, expiry, quantity, free quantity, rates and GST against the original bill. AI output is only a draft; no stock was posted.`);
   }catch(error){setPurchaseOcrNotice(error instanceof Error?error.message:'Bill scan failed. Please enter details manually.')}
   finally{setPurchaseOcrBusy(false)}
 }
