    // invoice_items has no created_at column in this schema; ordering by it caused print to fail.
    supabase.from('invoice_items').select('description,item_type,quantity,unit_price,discount_amount,tax_percent,line_total').eq('clinic_id',clinicId).eq('invoice_id',inv.id)
