   const patientName=patient?.full_name||'Patient record';
   w.document.open();w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>Pharmacy invoice ${safe(inv.invoice_no)}</title><style>*{box-sizing:border-box}body{font:13px Arial,sans-serif;margin:24px;color:#111}header{display:flex;justify-content:space-between;gap:20px;border-bottom:2px solid #222;padding-bottom:14px}h1{font-size:22px;margin:0 0 7px}h2{font-size:17px;margin:0 0 8px}.meta{margin:18px 0;padding:12px;border:1px solid #aaa}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{border:1px solid #999;padding:8px;text-align:left}th{background:#f1f1f1}.right{text-align:right}.totals{width:320px;margin-left:auto}.totals td{border:0;border-bottom:1px solid #ddd}.grand{font-size:16px;font-weight:bold}.foot{margin-top:45px;display:flex;justify-content:space-between}.logo{max-width:100px;max-height:70px;object-fit:contain;margin-bottom:8px}@media print{body{margin:12mm}.no-print{display:none}}</style></head><body><header><div>${logoUrl?`<img class="logo" src="${safe(logoUrl)}" alt="Pharmacy logo"><br>`:''}<h1>${safe(storeName||clinic?.name||'Clinic / Hospital')} — Pharmacy</h1><div>${safe(address)}</div><div>${storePhone||clinic?.phone?'Phone: '+safe(storePhone||clinic?.phone):''} ${storeEmail||clinic?.email?' · Email: '+safe(storeEmail||clinic?.email):''}</div>${drugLicense?`<div>Drug licence: ${safe(drugLicense)}</div>`:''}${gstin?`<div>GSTIN: ${safe(gstin)}</div>`:''}</div><div class="right"><h2>PHARMACY INVOICE</h2><b>${safe(inv.invoice_no)}</b><br>Date: ${safe(new Date(inv.created_at).toLocaleString('en-IN'))}<br>Status: ${safe(Number(inv.paid_amount)>=Number(inv.total_amount)?'PAID':Number(inv.paid_amount)>0?'PARTIAL':'DUE')}</div></header><div class="meta"><b>Patient:</b> ${safe(patientName)} &nbsp; <b>UHID:</b> ${safe(patient?.uhid||'—')} &nbsp; <b>Phone:</b> ${safe(patient?.phone||'—')} ${inv.admission_id?`<br><b>Admission No:</b> ${safe(admissionNo||'Admission number unavailable')}`:''}</div><table><thead><tr><th>#</th><th>Medicine / Product</th><th>Qty</th><th>Rate</th><th>GST</th><th>Amount</th></tr></thead><tbody>${rows||'<tr><td colspan="6">No invoice line items found.</td></tr>'}</tbody></table><table class="totals"><tr><td>Subtotal</td><td class="right">₹${Number(inv.subtotal||inv.total_amount).toFixed(2)}</td></tr><tr><td>GST</td><td class="right">₹${Number(inv.tax_amount||0).toFixed(2)}</td></tr><tr class="grand"><td>Total</td><td class="right">₹${Number(inv.total_amount).toFixed(2)}</td></tr><tr><td>Paid</td><td class="right">₹${Number(inv.paid_amount).toFixed(2)}</td></tr><tr class="grand"><td>Balance due</td><td class="right">₹${Math.max(0,Number(inv.total_amount)-Number(inv.paid_amount)).toFixed(2)}</td></tr></table><div class="foot"><span>Computer-generated invoice</span><span>Authorised signature: __________________</span></div><button class="no-print" onclick="window.print()">Print bill</button><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();
